'use strict';
/**
 * e-Service กลาง เทศบาลในฝัน — HTTP entry point (block B01).
 *
 * Other blocks do NOT edit this file. They drop in:
 *   server/modules/<name>/index.js        auto-loaded (alphabetical, optional `order`), see loadModules()
 *   server/modules/<name>/public/*        served at /static/<name>/*
 *   server/db/migrations/<name>.sql       applied once at startup (lib/db.js)
 *
 * Module export forms accepted:
 *   module.exports = function register(app, ctx) { app.get(...); app.use(router); }
 *   module.exports = { register(app, ctx) {...}, order: 50 }      (lower order loads first, default 100)
 *   module.exports = expressRouter                                 (mounted with app.use)
 *   module.exports = { router: expressRouter, order: 50 }
 * ctx = { config, db, clock, bugs, session, audit, crypto, format, codes, errors, view, counters, hooks, upload, express }
 *
 * Request pipeline:
 *   json/urlencoded parsers (10 MB) → /api/test/* guard (404 unless TEST_MODE=1)
 *   → SLA notify hook (all requests except /api/test/*) → /static → GET /api/health
 *   → session (req.user) → res.page() → modules → 404 (JSON for /api/*, page otherwise) → error handler
 */
require('express-async-errors'); // async route handlers: rejected promises reach the error handler

const fs = require('fs');
const path = require('path');
const express = require('express');

const config = require('./lib/config');
const dbm = require('./lib/db');
const clock = require('./lib/clock');
const bugs = require('./lib/bugs');
const errors = require('./lib/errors');
const session = require('./lib/session');
const view = require('./lib/view');

const MODULES_DIR = path.join(__dirname, 'modules');
const PUBLIC_DIR = path.join(__dirname, 'public');

// ------------------------------------------------------------------ database
const { applied } = dbm.init();
const { db } = dbm;

function bootstrapData() {
  const empty = !db.prepare('SELECT 1 FROM users LIMIT 1').get();
  if (config.testMode || empty) {
    require('./lib/reset').resetAll();
    return true;
  }
  return false;
}

// ------------------------------------------------------------------ app
const app = express();
app.disable('x-powered-by');
app.set('etag', false);

if (config.logRequests) {
  app.use((req, res, next) => {
    const t0 = process.hrtime.bigint();
    res.on('finish', () => {
      const ms = Number(process.hrtime.bigint() - t0) / 1e6;
      console.log(`${req.method} ${req.originalUrl.split('?')[0]} ${res.statusCode} ${ms.toFixed(1)}ms`);
    });
    next();
  });
}

// Bodies ≥ 6 MB must reach the handlers (CONTRACT §0.10). Multipart is parsed per-route by lib/upload.js.
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: false, limit: '10mb' }));

// /api/test/* exists only with TEST_MODE=1 (CONTRACT §0.8) — guard covers hooks added by any module.
app.use('/api/test', (req, res, next) => {
  if (!config.testMode) return errors.sendError(res, 'ROUTE_NOT_FOUND');
  next();
});

// SLA notifications + auto-cancel on every request except /api/test/* (CONTRACT §0.7 · A-30 · A-46).
app.use((req, res, next) => {
  if (req.path.startsWith('/api/test/') || req.path === '/api/test') return next();
  try {
    const hook = require('./lib/notify-hook');
    const run = typeof hook === 'function' ? hook : hook && hook.run;
    if (typeof run === 'function') run(req);
  } catch (e) {
    console.error('[notify-hook] failed:', e);
  }
  next();
});

app.use('/static', express.static(PUBLIC_DIR, { maxAge: config.isProd ? '1h' : 0 }));

// Availability probe (CONTRACT §6.6): exactly {"status":"ok"}, no login, independent of TEST_MODE.
app.get('/api/health', (req, res) => res.status(200).json({ status: 'ok' }));

app.use(session.loadSession);
app.use(view.attach);

// ------------------------------------------------------------------ modules
const ctx = {
  config, db, clock, bugs, session, errors, view, express,
  audit: require('./lib/audit'),
  crypto: require('./lib/crypto'),
  format: require('./lib/format'),
  codes: require('./lib/codes'),
  counters: require('./lib/counters'),
  hooks: require('./lib/hooks'),
  upload: require('./lib/upload'),
};

function isRouter(fn) {
  return typeof fn === 'function' && typeof fn.use === 'function' && typeof fn.handle === 'function';
}

function loadModules() {
  if (!fs.existsSync(MODULES_DIR)) return [];
  const entries = fs.readdirSync(MODULES_DIR, { withFileTypes: true })
    .filter((d) => d.isDirectory() && fs.existsSync(path.join(MODULES_DIR, d.name, 'index.js')))
    .map((d) => d.name)
    .sort();

  const loaded = [];
  for (const name of entries) {
    try {
      const mod = require(path.join(MODULES_DIR, name, 'index.js'));
      loaded.push({ name, mod, order: (mod && typeof mod.order === 'number') ? mod.order : 100 });
    } catch (e) {
      console.error(`[modules] FAILED to load "${name}":`, e);
      if (config.strictModules) throw e;
    }
  }
  loaded.sort((a, b) => a.order - b.order || a.name.localeCompare(b.name));

  const ok = [];
  for (const { name, mod } of loaded) {
    try {
      const pub = path.join(MODULES_DIR, name, 'public');
      if (fs.existsSync(pub)) app.use(`/static/${name}`, express.static(pub, { maxAge: config.isProd ? '1h' : 0 }));
      if (isRouter(mod)) app.use(mod);
      else if (typeof mod === 'function') mod(app, ctx);
      else if (mod && typeof mod.register === 'function') mod.register(app, ctx);
      else if (mod && isRouter(mod.router)) app.use(mod.router);
      else { console.warn(`[modules] "${name}" exports nothing mountable — skipped`); continue; }
      ok.push(name);
    } catch (e) {
      console.error(`[modules] FAILED to register "${name}":`, e);
      if (config.strictModules) throw e;
    }
  }
  return ok;
}

const modulesLoaded = loadModules();

// ------------------------------------------------------------------ 404 + errors
app.use('/api', (req, res) => errors.sendError(res, 'ROUTE_NOT_FOUND'));
app.use((req, res) => view.renderErrorPage(req, res, 404, 'page-not-found'));

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  if (res.headersSent) return next(err);
  const api = session.isApi(req);
  let apiErr;
  if (err instanceof errors.ApiError) apiErr = err;
  else if (err && err.type === 'entity.parse.failed') apiErr = new errors.ApiError('BAD_JSON');
  else if (err && err.type === 'entity.too.large') apiErr = new errors.ApiError('PAYLOAD_TOO_LARGE');
  else if (err && err.code === 'LIMIT_FILE_SIZE') apiErr = new errors.ApiError('FILE_TOO_LARGE');
  else {
    console.error(`[error] ${req.method} ${req.originalUrl.split('?')[0]}:`, err);
    apiErr = new errors.ApiError('INTERNAL');
  }
  if (api) return res.status(apiErr.status).json(apiErr.toJSON());
  try {
    if (apiErr.status === 403) return view.renderErrorPage(req, res, 403, 'forbidden');
    if (apiErr.code === 'NOT_FOUND') return view.renderErrorPage(req, res, 404, 'not-found');
    if (apiErr.status === 401) return res.redirect(302, '/login');
    return view.renderErrorPage(req, res, apiErr.status >= 500 ? 500 : apiErr.status, 'error');
  } catch (e2) {
    console.error('[error] error page failed:', e2);
    return res.status(500).type('text').send('เกิดข้อผิดพลาดภายในระบบ');
  }
});

// ------------------------------------------------------------------ start
function start() {
  const seeded = bootstrapData();
  const server = app.listen(config.port, '0.0.0.0', () => {
    console.log('==================================================================');
    console.log(` e-Service เทศบาลในฝัน  ·  http://localhost:${config.port}`);
    console.log(` TEST_MODE : ${config.testMode ? 'ON  (/api/test/* enabled, clock frozen)' : 'off (/api/test/* → 404)'}`);
    console.log(` BUG_MODE  : ${bugs.activeBugs().length ? bugs.activeBugs().join(',') : '(none — correct app)'}`
      + (bugs.unknownBugs.length ? `  ⚠ unknown: ${bugs.unknownBugs.join(',')}` : ''));
    console.log(` clock     : ${clock.nowIso()}${clock.isFrozen() ? ' (frozen)' : ''}`);
    console.log(` DB_PATH   : ${config.dbPath}${seeded ? '  (fresh seed)' : ''}`);
    console.log(` migrations: ${applied.length ? applied.join(', ') : '(none new)'}`);
    console.log(` modules   : ${modulesLoaded.join(', ') || '(none)'}`);
    console.log('==================================================================');
  });
  const stop = () => { server.close(() => { try { db.close(); } catch (_) { /* ignore */ } process.exit(0); }); setTimeout(() => process.exit(0), 2000).unref(); };
  process.on('SIGTERM', stop);
  process.on('SIGINT', stop);
  return server;
}

if (require.main === module) start();

module.exports = { app, start, bootstrapData };
